#include <bits/stdc++.h>
#define endl '\n'

using namespace std;

using ll = long long;

const ll V = 2e5, N = V + 5, P = 998244353;

int n, head[N], ans, res;
ll fac[N], ifac[N], sum;
struct
{
	int v, w, next;
} e[N << 1];

void add(int u, int v, int w)
{
	static int cnt = 0;
	e[++cnt] = {v, w, head[u]};
	head[u] = cnt;
}

ll qpow(ll a, ll b)
{
	ll res = 1;
	while (b)
	{
		if (b & 1)
			(res *= a) %= P;
		(a *= a) %= P;
		b >>= 1;
	}
	return res;
}

void init()
{
	fac[0] = 1;
	for (int i = 1; i <= V; ++i)
		fac[i] = fac[i - 1] * i % P;
	ifac[V] = qpow(fac[V], P - 2);
