**改两处：DFS 内只统计路径的配对方式，最后统一乘 `fac[ans]`，统计操作顺序。**

对于一个点，设相邻的 `1` 边有 `cnt` 条，令 \(t=\lfloor cnt/2\rfloor\)：

- `cnt` 为偶数：全部两两配对。
- `cnt` 为奇数：留一条作为路径端点，其余两两配对。

两种情况的方案数统一为
\[
\frac{cnt!}{2^t t!}.
\]
父边也参与配对，所以这里不用减去 `fl`。你原来的 `ans`、`res` 统计可以保留。

树上这些局部配对唯一确定一组路径；每个奇度点恰好作为一个端点，达到最少操作次数，同时每条 `1` 边只经过一次，达到最小路程。最后将这些路径排列，乘上 `ans!` 即可。

完整代码如下，修改处已标注：

```cpp
#include <bits/stdc++.h>
#define endl '\n'

using namespace std;

using ll = long long;

const ll V = 2e5, N = V + 5, P = 998244353;

int n, head[N], ans, res;
ll fac[N], ifac[N], sum;
struct
{
	int v, w, next;
} e[N << 1];

void add(int u, int v, int w)
{
	static int cnt = 0;
	e[++cnt] = {v, w, head[u]};
	head[u] = cnt;
}

ll qpow(ll a, ll b)
{
	ll res = 1;
	while (b)
	{
		if (b & 1)
			(res *= a) %= P;
		(a *= a) %= P;
		b >>= 1;
	}
	return res;
}

void init()
{
	fac[0] = 1;
	for (int i = 1; i <= V; ++i)
		fac[i] = fac[i - 1] * i % P;
	ifac[V] = qpow(fac[V], P - 2);
	for (int i = V; i >= 1; --i)
		ifac[i - 1] = ifac[i] * i % P;
}

void dfs(int u, int fa)
{
	int cnt = 0;
	bool fl = 0;
	for (int i = head[u], v; i; i = e[i].next)
	{
		if (e[i].w)
			++cnt;
		if ((v = e[i].v) == fa)
		{
			fl = e[i].w;
			continue;
		}
		dfs(v, u);
	}
	if (cnt == fl)
		return;
	// 修改 1：统计当前点的配对方式
	(sum *= fac[cnt] * ifac[cnt >> 1] % P * qpow((P + 1) / 2, cnt >> 1) % P) %= P;
	ans += ((cnt + 1) >> 1) - fl;
}

void solve()
{
	cin >> n;
	for (int i = 1, u, v, w; i < n; ++i)
	{
		cin >> u >> v >> w;
		add(u, v, w);
		add(v, u, w);
		res += w;
	}
	sum = 1;
	dfs(1, 0);
	// 修改 2：统计所有操作的排列
	(sum *= fac[ans]) %= P;
	cout << ans << ' ' << res << ' ' << sum << endl;
}

int main()
{
	ios::sync_with_stdio(false);
	cin.tie(nullptr);
	cout.tie(nullptr);
	// freopen("trails.in", "r", stdin);
	// freopen("trails.out", "w", stdout);
	int _ = 1;
	// cin >> _;
	init();
	while (_--)
		solve();
	return 0;
}
```

DFS 总时间为 \(O(n)\)：各点快速幂的总开销受 \(\sum cnt=2\,res\) 限制；预处理为 \(O(V+\log P)\)，空间为 \(O(V+n)\)。

