const int N = 12, M = 1 << N, P = 998244353;
int n, target, d[M], len[M], ways[M];
vector<pair<int, int>> e[N];
vector<int> a;
void dfs(int u, int fa, int s, int rt)
{
	if (u > rt)
		a.push_back(s);
	for (auto [v, w] : e[u])
		if (v != fa)
			dfs(v, u, s ^ w, rt);
}
int main()
{
	cin >> n;
	for (int i = 0, u, v, w; i < n - 1; ++i)
	{
		cin >> u >> v >> w;
		e[u].push_back({v, 1 << i});
		e[v].push_back({u, 1 << i});
		target |= w << i;
	}
	for (int i = 1; i <= n; ++i)
		dfs(i, 0, 0, i);
	fill(d, d + (1 << (n - 1)), 1e9);
	fill(len, len + (1 << (n - 1)), 1e9);
	d[0] = len[0] = 0;
	ways[0] = 1;
	priority_queue<tuple<int, int, int>, vector<tuple<int, int, int>>, greater<tuple<int, int, int>>> q;
	q.push({0, 0, 0});
	while (!q.empty())
	{
		auto [k, l, s] = q.top();
		q.pop();
		if (d[s] != k || len[s] != l)
			continue;
		for (int x : a)
		{
			int t = s ^ x, nk = k + 1, nl = l + __builtin_popcount(x);
			if (make_pair(nk, nl) < make_pair(d[t], len[t]))
			{
				d[t] = nk, len[t] = nl, ways[t] = ways[s];
				q.push({nk, nl, t});
			}
			else if (nk == d[t] && nl == len[t])
				ways[t] = (ways[t] + ways[s]) % P;
		}
	}
	cout << d[target] << ' ' << len[target] << ' ' << ways[target] << '\n';
}

