#include <bits/stdc++.h>
#define endl '\n'

using namespace std;

using ll = long long;
using ull = unsigned long long;

const int N = 8e4 + 5, B = 60;

int n, q, cnt, f[N], siz[N], rk[N], h[N], tr[N];
int head[N], nxt[N], it[N], st[N], ans[N];
int op[N], u[N], v[N], rt[N], son[N], old[N];
ull a[N], b[N][B], w[N], mask[N];

int find(int x)
{
	while (f[x] != x)
		x = f[x];
	return x;
}

void add(int x, int v)
{
	for (++x; x <= n + 1; x += x & -x)
		tr[x] += v;
}

int query(int k)
{
	int x = 0;
	for (int i = 1 << 16; i; i >>= 1)
		if (x + i <= n + 1 && tr[x + i] < k)
			k -= tr[x += i];
	return x;
}

void insert(int u, ull x, ull &s)
{
	while (x)
	{
		int i = 63 - __builtin_clzll(x);
		if (b[u][i])
			x ^= b[u][i];
		else
		{
			b[u][i] = x;
			s |= 1ull << i;
			++rk[u];
			return;
		}
	}
}

int calc(int u)
{
	ull x = a[u];
	if (rk[u] == B)
		return siz[u] - B;
	while (x)
	{
		int i = 63 - __builtin_clzll(x);
		if (!b[u][i])
			return siz[u] - rk[u] - 1;
		x ^= b[u][i];
	}
	return siz[u] - rk[u];
}

void modify(int id)
